import { configureStore, createSlice } from "@reduxjs/toolkit";

const firstSlice = createSlice({
  name: "data interpretation",
  initialState: {
    lang: "en",
    selectedStoryIndex: null,
  },
  reducers: {
    changeLang: (state, action) => {
      state.lang = action.payload;
    },
    setSelectedStoryIndex: (state, action) => {
      state.selectedStoryIndex = action.payload;
    },
  },
});

export const { changeLang, setSelectedStoryIndex } = firstSlice.actions;

//firstSlice.actions;
const firstStoreReducer = firstSlice.reducer;

export default configureStore({
  reducer: { firstStore: firstStoreReducer },
});