import { useEffect, useState } from "react";
import jsondata from "../json/table.json";
import TableStructure from "./TableStructure";
import { Button } from "@mui/material";
import arrayShuffle from "array-shuffle";
import Swal from "sweetalert2";
import Table_Instructions from "./Table_Instructions";
import help from "../Images/help.png";
import menu from "../Images/select_graph.png";
import { useTranslation } from "react-i18next";
import ReactGA from "react-ga4";
import useWebSocket from "react-use-websocket";
import logconfig from "../config/dbconfig.js";
import { SendLogData } from "../config/wslog.js";
import { useNavigate } from "react-router-dom";

function TableChild() {
  const [tabledata, setTableData] = useState(null);
  const [para, setPara] = useState([]);
  const [blankArr, setBlankArr] = useState([]);
  const [currkeys, setCurrkeys] = useState({});
  const [currkeysfeedback, setCurrkeysfeedback] = useState({});
  var [mainarr, setMainarr] = useState();
  const [dropdownStyles, setDropdownStyles] = useState({});
  const [disabledDropdowns, setDisabledDropdowns] = useState({});
  var [count, setCount] = useState(0);
  var [tablecount, setTablecount] = useState(0);
  var [tablename, setTablename] = useState("");
  var [tablecaption, setTablecaption] = useState("");
  var [previnfo, setPrevinfo] = useState("");
  var [flag, setFlag] = useState(true);
  var [flag1, setFlag1] = useState(false);
  const [open1, setOpen1] = useState(false);
  var [heplok, setHeplok] = useState(false);
  let [score, setScore] = useState(0);
  const { t, i18n } = useTranslation();
  const navigate = useNavigate();
  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const [pageName, setPageName] = useState("Table page");

  useEffect(() => {
    mainarr = arrayShuffle(Object.values(jsondata));
    setMainarr(mainarr);
  }, []);

  useEffect(() => {
    if (tablecount < Object.keys(jsondata).length) {
      const data = mainarr[tablecount];
      setTableData(data.table);

      // Splitting the paragraph into words
      const paragraph = data.data.paragraph.split(" ");
      setPara(paragraph);
      setTablename(data.data.title);
      setTablecaption(data.data.caption);
      setPrevinfo(data.data.prev_details);

      const tempBlankArr = data.data.data;
      setBlankArr(tempBlankArr);

      // Creating a map for easy key-options lookup
      const keyMap = tempBlankArr.reduce((acc, item) => {
        acc[item.key] = item.options;
        return acc;
      }, {});

      const keyMapfeedback = tempBlankArr.reduce((ele, item) => {
        ele[item.key] = item.feedback;
        return ele;
      }, {});
      setCurrkeys(keyMap);
      setCurrkeysfeedback(keyMapfeedback)
    } else {
      setFlag1(true);
    }
  }, [tablecount]);

  useEffect(() => {
    if (Object.keys(currkeys).length != 0) {
      if (Object.keys(currkeys).length == count) {
        setFlag(false);
        Swal.fire({
          title: "Correct",
          text: "All selected data is correct!",
          icon: "success"
        });
      }
    }
  }, [count]);

  const handleonchange = (e, val, index) => {
    const sanitizedId = val.replace(/[^a-zA-Z0-9_-]/g, "_");
    if (Object.keys(currkeys).includes(e.target.value)) {
      setDropdownStyles((prevStyles) => ({
        ...prevStyles,
        [sanitizedId]: { backgroundColor: "#098B0D", color: "white" },
      }));
      setDisabledDropdowns((prevDisabled) => ({
        ...prevDisabled,
        [sanitizedId]: true, // Mark this dropdown as disabled
      }));
      setCount((prevCount) => prevCount + 1);
      ReactGA.event({
        action:
          'English Data interpretation | CDAC-OlabsNxtG-En-28 | Selected correct option from dropdown.',
        category: 'English CDAC-OlabsNxtG-En-28 |  Table page Selected correct option from dropdown',
        label:
          'English CDAC-OlabsNxtG-En-28 |  Table page Selected correct option from dropdown.',
      });
      SendLogData(
        sendJsonMessage,
        pageName,
        'Selected correct option from dropdown',
        "Clicked",
        'Selected correct option from dropdown.',
        [{ input: { sanitizedId }, answer: { sanitizedId }, result: "correct" }]
      );
    } else {
      setDropdownStyles((prevStyles) => ({
        ...prevStyles,
        [sanitizedId]: { backgroundColor: "#BF4C4C", color: "white" },
      }));
      const abc = e.target.id.replace(/[_]$/, "%");
      const feedback = currkeysfeedback[abc]
      Swal.fire({
        title: "Incorrect Word!",
        text: `${feedback}`,
        icon: "error",
      });
    }
  };

  const handlenxtbtn = () => {
    setTableData(null);
    setPara([]);
    setBlankArr([]);
    setCurrkeys({});
    setDropdownStyles({});
    setDisabledDropdowns({});
    setFlag(true);
    count = 0;
    setCount(count);
    tablecount = tablecount + 1;
    setTablecount(tablecount);
    setScore((prev) => prev + 1);
    ReactGA.event({
      action:
        "English Data interpretation | CDAC-OlabsNxtG-En-28 | Clicked on 'Next button",
      category: "English CDAC-OlabsNxtG-En-28 | Table page 'Next' button clicked",
      label:
        "English CDAC-OlabsNxtG-En-28 | Table page 'Next' button clicked to perform another table example.",
    });
    SendLogData(
      sendJsonMessage,
      pageName,
      'Table page "Next" button.',
      "Clicked",
      'Table page "Next" button clicked perform next table data interpretation.'
    );
  };

  const handleskipbtn = () => {
    setTableData(null);
    setPara([]);
    setBlankArr([]);
    setCurrkeys({});
    setDropdownStyles({});
    setDisabledDropdowns({});
    setFlag(true);
    count = 0;
    setCount(count);
    tablecount = tablecount + 1;
    setTablecount(tablecount);
    ReactGA.event({
      action:
        "English Data interpretation | CDAC-OlabsNxtG-En-28 | Clicked on 'Skip button",
      category: "English CDAC-OlabsNxtG-En-28 | Table page 'Skip' button clicked",
      label:
        "English CDAC-OlabsNxtG-En-28 | Table page 'Skip' button clicked to perform another table example.",
    });
    SendLogData(
      sendJsonMessage,
      pageName,
      'Table page "Skip" button.',
      "Clicked",
      'Table page "Skip" button clicked perform next table data interpretation.'
    );
  };

  const handlerestartbtn = () => {
    ReactGA.event({
      action:
        'English Data interpretation| CDAC-OlabsNxtG-En-28 | Clicked on "Restart" button',
      category: 'English CDAC-OlabsNxtG-En-28 | "Restart" button clicked',
      label:
        'English CDAC-OlabsNxtG-En-28 | "Restart" button clicked and Table data interpretation restarted',
    });
    SendLogData(
      sendJsonMessage,
      pageName,
      '"Restart" button',
      "Clicked",
      '"Restart" button clicked and table data interpretation restart.'
    );
    window.location.reload();
  };

  const handlemainmenubtn = () => {
    ReactGA.event({
      action:
        'English Data interpretation| CDAC-OlabsNxtG-En-28 | Clicked on "Main menu" button',
      category: 'English CDAC-OlabsNxtG-En-28 | "Main menu" button clicked',
      label:
        'English CDAC-OlabsNxtG-En-28 | "Main menu" button clicked and main menu displayed.',
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      '"Main menu" button',
      "Clicked",
      '"Main menu" button clicked and main menu displayed.'
    );
    navigate("/launchpage/englishactivity");
  };

  const handleClose1 = () => {
    setOpen1(false);
  };

  const handleHelp = () => {
    setOpen1(true);
    setHeplok(true);
    ReactGA.event({
      action:
        'English Data interpretation| CDAC-OlabsNxtG-En-28 | Clicked on "Help" button',
      category: 'English CDAC-OlabsNxtG-En-28 | "Help" button clicked',
      label:
        'English CDAC-OlabsNxtG-En-28 | "Help" button clicked for Table data interpretation instructions.',
    });
    SendLogData(
      sendJsonMessage,
      pageName,
      '"Help" button',
      "Clicked",
      '"Help" button clicked for table data interpretation instructions.'
    );
  }

  const menuslelect = () => {
    navigate("/launchpage/englishactivity")
  }

  return (
    <div
      className="row"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <Table_Instructions
        handleClose1={handleClose1}
        open1={open1}
        setOpen1={setOpen1}
        heplok={heplok}
      />

      {flag1 == true ? (
        <div className="col-sm-12 align-items-center justify-content-center ">
          <div
            className="d-flex justify-content-end text-center "
            variant="contained"
            onClick={menuslelect}
          >
            <img src={menu} title={t("select_graph")}></img>
          </div>

          <div
            className="d-flex align-items-center justify-content-center"
            style={{
              display: "inline-block",
              position: "absolute",
              top: "50%",
              left: "50%",
              transform: "translate(-50%, -50%)",
            }}
          >

            <div
              className="text-center"
              style={{
                boxShadow: "rgba(0, 0, 0, 0.24) 0px 3px 8px",
                padding: "7vh 4vh 7vh 4vh",
                background: "#EDF6FA",
              }}
            >
              <p style={{ fontWeight: "bolder", fontSize: "calc(.6rem + .4vw)" }}>
                You have completed {score} of {Object.keys(jsondata).length} table data interpretations.<br></br>Click on the "RESTART" button to practice table data interpretation again.
              </p>
              <div>
                <Button variant="contained" onClick={handlerestartbtn} style={{fontSize: "calc(.6rem + .4vw)", backgroundColor: "#0F477E"}}>
                  {t("restart")}
                </Button>
              </div>
              <p style={{ fontWeight: "bolder", fontSize: "calc(.6rem + .4vw)", marginTop: "1vh" }}>To start with other types of data interpretation, click on the "MAIN MENU" button.</p>
              <div>
                <Button variant="contained" onClick={handlemainmenubtn} style={{fontSize: "calc(.6rem + .4vw)", backgroundColor: "#0F477E"}}>
                  {t("mainmenu")}
                </Button>
              </div>
            </div>
          </div>
        </div>

      ) : (
        <div
          className="col-sm-12 align-items-center justify-content-center"
          style={{
            width: "100%",
            height: "100%",
          }}
        >

          <div className="d-flex">
            <div className="col text-center" style={{ fontSize: "calc(1rem + .4vw)" }} >
              <b>Table</b>
            </div>
            <div
              className=" text-center "
              variant="contained"
              onClick={menuslelect}
            >
              <img src={menu} title={t("select_graph")}></img>
            </div>

            <div
              className=" text-center "
              variant="contained"
              onClick={handleHelp}
            >
              <img src={help} title={t("help")}></img>
            </div>
          </div>

          <div
            style={{
              boxShadow:
                "rgba(60, 64, 67, 0.3) 0px 1px 2px 0px, rgba(60, 64, 67, 0.15) 0px 2px 6px 2px",
              backgroundColor: "white",
              marginTop: "2vh",
              padding: "20px",
            }}
          >

            <div className="d-flex justify-content-center align-items-center mt-5">
              {tabledata ? (
                <TableStructure table={tabledata} />
              ) : (
                <p>Loading table...</p>
              )}

            </div>
            <p className="text-center" style={{ fontSize: "calc(.6rem + .4vw)" }}>Fig: {tablecaption}</p>

            <div className="text-center" style={{ fontSize: "calc(.6rem + .4vw)" }} dangerouslySetInnerHTML={{ __html: previnfo }}></div>
            <div
              className="d-flex"
              style={{
                backgroundColor: "#D6EAF8",
                borderRadius: "13px",
                boxShadow: "0px 4px 7px #00000029",
                display: "block",
                marginLeft: "auto",
                marginRight: "auto",
                marginTop: "2%",
                marginBottom: "1%",
                padding: "1%",
                fontWeight: "bolder",
                fontFamily: "Arial",
                background: "#EDF6FA",
                cursor: "pointer",
                flexWrap: "wrap",
                marginTop: "2vh",
                fontSize: "calc(.6rem + .4vw)"
              }}
            >
              {para.length > 0 ? (
                para.map((paraword, index) => {
                  const cleanedWord = paraword.replace(/[^a-zA-Z0-9%]/g, ""); // Removing punctuation for matching
                  if (currkeys[cleanedWord]) {
                    return (
                      <select
                      className=""
                        key={index}
                        id={cleanedWord.replace(/[^a-zA-Z0-9_-]/g, "_")}
                        style={
                          dropdownStyles[
                          cleanedWord.replace(/[^a-zA-Z0-9_-]/g, "_")
                          ] || {}
                        }
                        onChange={(e) => handleonchange(e, cleanedWord, index)}
                        disabled={
                          !!disabledDropdowns[
                          cleanedWord.replace(/[^a-zA-Z0-9_-]/g, "_")
                          ]
                        }
                      >
                        <option>Select option</option>
                        {currkeys[cleanedWord].map((option, idx) => (
                          <option key={idx} value={option}>
                            {option}
                          </option>
                        ))}
                      </select>
                    );
                  } else {
                    return <span key={index}>&nbsp;{paraword}&nbsp;</span>;
                  }
                })
              ) : (
                <p>Loading paragraph...</p>
              )}
            </div>
           </div>
          <div>
            <div
              className="d-flex justify-content-around"
              style={{ marginTop: "2vh" }}
            >
              <Button
                variant="contained"
                onClick={handleskipbtn}
                sx={{ backgroundColor: "#0F477E",fontSize: "calc(.6rem + .4vw)" }}
              >
                {t("skip")}
              </Button>

              <Button
                variant="contained"
                onClick={handlenxtbtn}
                disabled={flag}
                sx={{ backgroundColor: "#0F477E",fontSize: "calc(.6rem + .4vw)" }}
              >
                {t("next")}
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default TableChild;





