import { useEffect, useRef, useState } from "react";
import { Carousel, Form } from "react-bootstrap";
import { Button } from "@mui/material";
import Swal from "sweetalert2";
import jsondata from "../json/bar.json";
import Chart from "chart.js/auto";
import { ToastContainer } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import Bar_Instructions from "./Bar_Instructions";
import help from "../Images/help.png";
import menu from "../Images/select_graph.png";
import { useTranslation } from "react-i18next";
import ReactGA from "react-ga4";
import useWebSocket from "react-use-websocket";
import logconfig from "../config/dbconfig.js";
import { SendLogData } from "../config/wslog.js";
import { useNavigate } from "react-router-dom";

function BarChild() {
  const [tablecount, setTablecount] = useState(0);
  const [activeIndex, setActiveIndex] = useState(0);
  const [answers, setAnswers] = useState({});
  const [isComplete, setIsComplete] = useState(false);
  const questions = jsondata[tablecount]?.data?.questionset || [];
  const [currfeedback, setCurrfeedback] = useState();
  const [currIndex, setCurrindex] = useState();
  const [disabledQuestions, setDisabledQuestions] = useState({});
  const [count, setCount] = useState(0);
  const chartRef = useRef(null);
  const chartCanvasRef = useRef(null);   // ✅ This is for the canvas DOM element
  var [flag, setFlag] = useState(false);
  var [flag1, setFlag1] = useState(false);
  const [open1, setOpen1] = useState(false);
  var [heplok, setHeplok] = useState(false);
  let [score, setScore] = useState(0);
  var [grapdhcaption, setGraphcaption] = useState(jsondata[tablecount]?.data?.caption);
  let [previnfo, setPrevinfo] = useState(jsondata[tablecount]?.data?.prev_details);
  const { t, i18n } = useTranslation();
  const navigate = useNavigate();
  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const [pageName, setPageName] = useState("Bar chart page");

  useEffect(() => {
    const chartData = jsondata[tablecount]?.barchart;
    if (!chartData) {
      setFlag1(true);
      return;
    }
    const canvas = document.getElementById("myChart");
    if (!canvas) {
      console.error("Canvas not found");
      return;
    }
    const ctx = canvas.getContext("2d");
    // Destroy previous chart if it exists
    if (chartRef.current) {
      chartRef.current.destroy();
    }
    // Wait for DOM to stabilize before drawing chart
    requestAnimationFrame(() => {
      chartRef.current = new Chart(ctx, {
        type: "bar",
        data: {
          labels: chartData.names,
          datasets: [
            {
              label: chartData.title,
              data: chartData.values,
              backgroundColor: chartData.colors,
            },
          ],
        },
        options: {
          responsive: true,
          maintainAspectRatio: false, // Very important for full height
          plugins: {
            title: {
              display: false,
              text: chartData.title,
            },
            legend: {
              display: false,
            },
          },
          scales: {
            y: {
              beginAtZero: true,
            },
          },
        },
      });
    });
  }, [tablecount]);

  const handleNext = () => {
    setFlag(true);
    if (activeIndex < questions.length - 1) {
      setActiveIndex((prevIndex) => prevIndex + 1);
      ReactGA.event({
        action:
          "English Data interpretation | CDAC-OlabsNxtG-En-28 | Clicked on 'Next button",
        category: "English CDAC-OlabsNxtG-En-28 | Bar chart page 'Next' button clicked",
        label:
          "English CDAC-OlabsNxtG-En-28 | Bar chart page 'Next' button clicked to perform another Bar chart example.",
      });
      SendLogData(
        sendJsonMessage,
        pageName,
        'Bar chart page "Next" button.',
        "Clicked",
        'Bar chart page "Next" button clicked perform next Bar chart data interpretation.'
      );

    } else {
      Swal.fire({
        title: `You attempted ${count} out of ${questions.length} questions`,
        icon: "info",
      });
      setIsComplete(true);
    }
  };

  const handlePrev = () => {
    if (activeIndex > 0) {
      setActiveIndex((prevIndex) => prevIndex - 1);
    }
  };

  const handleAnswerChange = (questionIndex, selectedOption) => {
    setAnswers((prevAnswers) => ({
      ...prevAnswers,
      [questionIndex]: selectedOption,
    }));
    setCurrfeedback(
      jsondata[tablecount].data.questionset[questionIndex].feedback
    );
    setCurrindex(questionIndex);
    setFlag(false);
  };

  const handlesubmitbtn = () => {
    if (currIndex == null || currIndex == undefined) {
      alert("select an option.");
    } else {
      if (flag === true) {
        alert("select an option.");
      } else if (
        flag == false &&
        answers[currIndex] === questions[currIndex].correctans
      ) {
        setCount((prevCount) => prevCount + 1);
        Swal.fire({
          title: "Correct",
          html: `<b>${questions[currIndex].correctans}</b> is the correct answer.`,
          icon: "success",
        });
        setDisabledQuestions((prev) => ({
          ...prev,
          [currIndex]: true,
        }));
        if (Object.keys(answers).length === questions.length) {
          setIsComplete(true);
          Swal.fire({
            title: `You attempted ${count + 1} out of ${questions.length
              } questions`,
            icon: "info",
          });
        }
      } else {
        Swal.fire({
          title: "Incorrect",
          text: currfeedback,
          icon: "error",
        });
        ReactGA.event({
          action:
            "English Data interpretation | CDAC-OlabsNxtG-En-28 | Clicked on 'Submit answer button",
          category: "English CDAC-OlabsNxtG-En-28 | Bar chart page 'Submit answer' button clicked",
          label:
            "English CDAC-OlabsNxtG-En-28 | Bar chart page 'Submit answer' button clicked to check the selected answer.",
        });
        SendLogData(
          sendJsonMessage,
          pageName,
          'Bar chart page "submit answer" button.',
          "Clicked",
          'Bar chart page "Submit answer" button clicked to check the selected answer.'
        );

      }
    }
  };

  const handleNextGraph = () => {
    setTablecount((prev) => prev + 1);
    setScore((prev) => prev + 1);
    setAnswers({});
    setIsComplete(false);
    setCurrfeedback(null);
    setCurrindex(null);
    setActiveIndex(0);
    setDisabledQuestions({});
    setCount(0);
    ReactGA.event({
      action:
        "English Data interpretation | CDAC-OlabsNxtG-En-28 | Clicked on 'Next button",
      category: "English CDAC-OlabsNxtG-En-28 | Bar chart page 'Next' button clicked",
      label:
        "English CDAC-OlabsNxtG-En-28 | Bar chart page 'Next' button clicked to perform another Bar chart example.",
    });
    SendLogData(
      sendJsonMessage,
      pageName,
      'Bar chart page "Next" button.',
      "Clicked",
      'Bar chart page "Next" button clicked perform next Bar chart data interpretation.'
    );
  };

  const restartbtn = () => {
    setTablecount(0);
    setAnswers({});
    setIsComplete(false);
    setCurrfeedback(null);
    setCurrindex(null);
    setActiveIndex(0);
    setDisabledQuestions({});
    setCount(0);
    ReactGA.event({
      action:
        'English Data interpretation| CDAC-OlabsNxtG-En-28 | Clicked on "Restart" button',
      category: 'English CDAC-OlabsNxtG-En-28 | "Restart" button clicked',
      label:
        'English CDAC-OlabsNxtG-En-28 | "Restart" button clicked and Bar chart data interpretation restarted',
    });
    SendLogData(
      sendJsonMessage,
      pageName,
      '"Restart" button',
      "Clicked",
      '"Restart" button clicked and Bar chart data interpretation restart.'
    );
    window.location.reload();
  };

  const handlemainmenubtn = () => {
    ReactGA.event({
      action:
        'English Data interpretation| CDAC-OlabsNxtG-En-28 | Clicked on "Main menu" button',
      category: 'English CDAC-OlabsNxtG-En-28 | "Main menu" button clicked',
      label:
        'English CDAC-OlabsNxtG-En-28 | "Main menu" button clicked and main menu displayed.',
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      '"Main menu" button',
      "Clicked",
      '"Main menu" button clicked and main menu displayed.'
    );
    navigate("/launchpage/englishactivity");
  };

  const handleClose1 = () => {
    setOpen1(false);
  };

  const handleHelp = () => {
    setOpen1(true);
    setHeplok(true);
    ReactGA.event({
      action:
        'English Data interpretation| CDAC-OlabsNxtG-En-28 | Clicked on "Help" button',
      category: 'English CDAC-OlabsNxtG-En-28 | "Help" button clicked',
      label:
        'English CDAC-OlabsNxtG-En-28 | "Help" button clicked for Bar chart data interpretation instructions.',
    });
    SendLogData(
      sendJsonMessage,
      pageName,
      '"Help" button',
      "Clicked",
      '"Help" button clicked for Bar chart data interpretation instructions.'
    );
  };

  const menuslelect = () => {
    navigate("/launchpage/englishactivity")
  }

  return (
    <div
      className="bg-white row"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <Bar_Instructions
        handleClose1={handleClose1}
        open1={open1}
        setOpen1={setOpen1}
        heplok={heplok}
      />

      {flag1 == true ? (
        <div className="col-sm-12 align-items-center justify-content-center">
          <div
            className="d-flex justify-content-end text-center "
            variant="contained"
            onClick={menuslelect}
          >
            <img src={menu} title={t("select_graph")}></img>
          </div>
          <div
            className="d-flex align-items-center justify-content-center"
            style={{
              display: "inline-block",
              position: "absolute",
              top: "50%",
              left: "50%",
              transform: "translate(-50%, -50%)",
            }}
          >

            <div
              className="text-center"
              style={{
                boxShadow: "rgba(0, 0, 0, 0.24) 0px 3px 8px",
                padding: "7vh 4vh 7vh 4vh",
                background: "#EDF6FA",
              }}
            >
              <p style={{ fontWeight: "bolder", fontSize: "calc(.6rem + .4vw)" }}>
                You have completed {score} of {Object.keys(jsondata).length} bar chart data interpretation. <br></br>Click on the "RESTART" button to practice bar chart data interpretation again.
              </p>
              <div>
                <Button variant="contained" onClick={restartbtn} style={{backgroundColor: "#0F477E", fontSize: "calc(.6rem + .4vw)"}}>
                  {t("restart")}
                </Button>
              </div>
              <p style={{ fontWeight: "bolder", fontSize: "calc(.6rem + .4vw)", marginTop: "1vh" }}>To start with other types of data interpretation, click on the "MAIN MENU" button.</p>
              <div>
                <Button variant="contained" onClick={handlemainmenubtn} style={{backgroundColor: "#0F477E", fontSize: "calc(.6rem + .4vw)"}}>
                  {t("mainmenu")}
                </Button>
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="">
          <div className="d-flex justify-content-end ">
            <div className="col text-center" style={{ fontSize: "calc(1rem + .4vw)" }} >
              <b>Bar chart</b>
            </div>
            <div
              className="text-center "
              variant="contained"
              onClick={menuslelect}
            >
              <img src={menu} title={t("select_graph")}></img>
            </div>
            <div
              className=" text-center "
              variant="contained"
              onClick={handleHelp}
            >
              <img src={help} title={t("help")}></img>
            </div>
          </div>
          <div
            className="d-flex align-items-center justify-content-center"
            style={{ height: "42.5vh" }}
          >
            <div
              style={{
                position: "relative",
                width: "90%",
                maxWidth: "700px",
                height: "100%",
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              <div
                style={{
                  position: "relative",
                  width: "100%",
                  height: "100%", // Ensures canvas grows inside this
                }}
              >
                <canvas
                  id="myChart"
                  ref={chartCanvasRef}
                  style={{
                    width: "100%",
                    height: "100%",
                  }}
                ></canvas>
              </div>
              <p
                className="text-center"
                style={{
                  fontSize: "calc(.6rem + .4vw)",
                  color: "#000",
                }}
              >
                Fig: {grapdhcaption}
              </p>
            </div>
          </div>

          <div className="text-center" style={{ fontSize: "calc(.6rem + .4vw)" }} dangerouslySetInnerHTML={{ __html: previnfo }}></div>

          <div className="" style={{ height: "43vh", }}>
            <Carousel
              activeIndex={activeIndex}
              interval={null}
              prevLabel={null}
              nextLabel={null}
              style={{
                backgroundColor: "#EDF6FA", // ✅ Carousel background color
                margin: "20px auto",        // ✅ Margin (top/bottom & auto center)
                borderRadius: "10px",       // ✅ Optional: rounded corners
                padding: "10px",            // ✅ Optional: inner space
                width: "90%",               // ✅ Optional: control overall width
              }}
              prevIcon={
                <span
                  aria-hidden="true"
                  className="carousel-control-prev-icon"
                  onClick={handlePrev}
                  style={{
                    cursor: activeIndex > 0 ? "pointer" : "not-allowed",
                    backgroundColor: "black"
                  }}
                />
              }
              nextIcon={
                <span
                  aria-hidden="true"
                  className="carousel-control-next-icon"
                  onClick={handleNext}
                  style={{
                    cursor:
                      activeIndex < questions.length - 1
                        ? "pointer"
                        : "not-allowed",
                    backgroundColor: "black"
                  }}
                />
              }
            >
              {questions.map((question, index) => (
                <Carousel.Item
                  key={index}
                  style={{ height: "100%", backgroundColor: "#EDF6FA", }}
                >
                  <div
                    className="d-flex justify-content-center align-items-center"
                    style={{ height: "100%" }}
                  >
                    <div className="p-5 text-center" style={{ fontSize: "calc(.6rem + .4vw)" }}>
                      <span className="mb-4">{`Q${index + 1}: ${question.question
                        }`}</span>
                      <Form>
                        {question.options.map((option, optIndex) => (
                          <Form.Check
                            key={optIndex}
                            type="radio"
                            name={`question-${index}`}
                            label={option}
                            id={`q-${index}-option-${optIndex}`}
                            checked={answers[index] === option}
                            onChange={() =>
                              !disabledQuestions[index] &&
                              handleAnswerChange(index, option)
                            }
                            disabled={disabledQuestions[index]}
                            className="text-left"
                          />
                        ))}
                      </Form>
                      <div className="mt-3">
                        <Button
                          variant="contained"
                          onClick={handlesubmitbtn}
                          disabled={disabledQuestions[index]}
                          sx={{ backgroundColor: "#0F477E",fontSize: "calc(.6rem + .4vw)" }}
                        >
                          {t("verify")}
                        </Button>
                      </div>
                    </div>
                  </div>
                </Carousel.Item>
              ))}
            </Carousel>

            {isComplete && tablecount >= Object.keys(jsondata).length - 1 ? (
              <div className="text-center mt-3">
                <Button variant="contained" onClick={handleNextGraph} sx={{ backgroundColor: "#0F477E", fontSize: "calc(.6rem + .4vw)" }}>
                  {t("finish")}
                </Button>
              </div>
            ) : (
              isComplete && (
                <div className="text-center mt-3">
                  <Button variant="contained" onClick={handleNextGraph} sx={{ backgroundColor: "#0F477E",fontSize: "calc(.6rem + .4vw)" }}>
                    {t("nextgraph")}
                  </Button>
                </div>
              )
            )}
          </div>
        </div>
      )}
      <ToastContainer></ToastContainer>
    </div>
  );
}

export default BarChild;
