import React from "react";

function TableStructure({ table }) {
  const { columns, rows } = table;

  return (
    <div style={{overflowX:"auto",fontSize: "calc(.6rem + .4vw)"}}>
      <table border="1" cellPadding="10" cellSpacing="0" >
        <thead>
          <tr>
            <th style={{border:"1px solid black",fontSize: "calc(.6rem + .4vw)"}}></th> 
            {columns.map((col, index) => (
              <th key={index} style={{border:"1px solid black", backgroundColor:"lightblue",fontSize: "calc(.6rem + .4vw)"}}>{col}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row, rowIndex) => (
            <tr key={rowIndex} style={{border:"1px solid black"}}>
              <td style={{border:"1px solid black", backgroundColor:"lightblue"}}>
                <strong>{row.type}</strong>
              </td>
              {row.data.map((cell, colIndex) => (
                <td key={colIndex} style={{border:"1px solid black", textAlign:"center",fontSize: "calc(.6rem + .4vw)"}}>{cell}</td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default TableStructure;
