import { useEffect, useRef, useState } from "react";
import Chart from "chart.js/auto";
import { Button } from "@mui/material";
import jsondata from "../json/pie.json";
import menu from "../Images/select_graph.png";
import arrayShuffle from "array-shuffle";
import Swal from "sweetalert2";
import help from "../Images/help.png";
import Pie_Instructions from "./Pie_Instructions";
import { useTranslation } from "react-i18next";
import ReactGA from "react-ga4";
import useWebSocket from "react-use-websocket";
import logconfig from "../config/dbconfig.js";
import { SendLogData } from "../config/wslog.js";
import { useNavigate } from "react-router-dom";

function PieChild() {
  const [tablecount, setTablecount] = useState(0);
  const [para, setPara] = useState([]);
  const [blankspaces, setBlankspaces] = useState([]);
  const [bsword, setBsword] = useState([]);
  const chartRef = useRef(null);
  const [mainarr, setMainarr] = useState(Object.values(jsondata));
  var [correctcount, setCorrectcount] = useState(0);
  var [shuffled, setShuffled] = useState();
  var [flag, setFlag] = useState(true);
  var [flag1, setFlag1] = useState(false);
  const [open1, setOpen1] = useState(false);
  var [heplok, setHeplok] = useState(false);
  let [score, setScore] = useState(0);
  const [mobil_id, setmobi_id1] = useState(""); // for mobile drag drop
  let details = navigator.userAgent;
  let regexp = /android|iphone|kindle|ipad/i;
  let isMobileDevice = regexp.test(details);
  const { t, i18n } = useTranslation();
  const navigate = useNavigate();
  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const [pageName, setPageName] = useState("Pie chart page");
  var [chartcaption, setChartcaption] = useState("");
  var [previnfo, setPrevinfo] = useState("");

  useEffect(() => {
    shuffled = arrayShuffle(mainarr);
    setShuffled(shuffled);
  }, [mainarr]);

  useEffect(() => {
    if (tablecount >= shuffled.length) {
      console.error("No more data available for tablecount:", tablecount);
      flag1 = true;
      setFlag1(flag1);
      return;
    }

    const chartData = shuffled[tablecount]?.piechart; // Safely access piechart
    if (!chartData) {
      console.error("Pie chart data not found for tablecount:", tablecount);
      return;
    }

    if (chartData) {
      const canvas = document.getElementById("myChart");
      if (!canvas) {
        console.error("Canvas element not found");
        return;
      }

      const ctx = canvas.getContext("2d");
      if (chartRef.current) {
        chartRef.current.destroy();
      }
      chartRef.current = new Chart(ctx, {
        type: "pie",
        data: {
          labels: chartData.names,
          datasets: [
            {
              backgroundColor: chartData.colors,
              data: chartData.values,
            },
          ],
        },
        options: {
          plugins: {
            title: {
              display: false,
              text: chartData.title,
            },
            legend: {
              position: "right", //  move legend to right
              labels: {
                boxWidth: 20,
                padding: 15,
              },
            },
          },
          responsive: true,
          maintainAspectRatio: false,
        },
      });

      const fetchData = async () => {
        const data = shuffled[tablecount];
        if (data) {
          const paragraph = data.data.paragraph.split(" ");
          const blanks = data.data.blankspaces.map((val) => ({
            word: val.word,
            feedback: val.feedback,
            placed: false, // Ensure initial unplaced state
          }));
          setPara(paragraph);
          setBlankspaces(blanks);
          setBsword(arrayShuffle(blanks.map((val) => val.word)));
          setChartcaption(data.data.caption);
          setPrevinfo(data.data.prev_details);
        }
      };
      fetchData();
    }
  }, [tablecount]);

  // Debugging updated blankspaces
  useEffect(() => {
    console.log("Updated blankspaces:", blankspaces);
  }, [blankspaces]);

  const handleOndrop1 = (e) => {
    const droppedword = e.dataTransfer.getData("id1");
    const bsoriginalword = e.target.id;
    document.getElementById(bsoriginalword).innerText = droppedword;
    if (droppedword === bsoriginalword) {
      document.getElementById(bsoriginalword).style.backgroundColor = "#098B0D";
      document.getElementById(bsoriginalword).style.color = "white";
      document.getElementById(bsoriginalword).style.pointerEvents = "none"; // Disable interaction (disable drop)
      console.log(document.getElementById(bsoriginalword));
      correctcount = correctcount + 1;
      setCorrectcount(correctcount);
      if (blankspaces.length === correctcount) {
        setFlag(false);
        Swal.fire({
          title: "Correct",
          text: "All answers are correct!",
          icon: "success"
        });
      }
    } else {
      document.getElementById(bsoriginalword).style.backgroundColor = "#BF4C4C";
      document.getElementById(bsoriginalword).style.color = "white";
    }
  };

  const handleOntouchend = (e) => {
    const droppedword = mobil_id;
    const bsoriginalword = e.target.id;
    document.getElementById(bsoriginalword).innerText = droppedword;
    if (droppedword === bsoriginalword) {
      document.getElementById(bsoriginalword).style.backgroundColor = "#098B0D";
      document.getElementById(bsoriginalword).style.color = "white";
      document.getElementById(bsoriginalword).style.pointerEvents = "none"; // Disable interaction (disable drop)
      correctcount = correctcount + 1;
      setCorrectcount(correctcount);
      if (blankspaces.length === correctcount) {
        setFlag(false);
      }
    } else {
      document.getElementById(bsoriginalword).style.backgroundColor = "#BF4C4C";
      document.getElementById(bsoriginalword).style.color = "white";
    }
  };

  const handledragstart = (e) => {
    e.dataTransfer.setData("id1", e.target.id);
  };

  const handletouchstart = (e) => {
    const word = e.target.id;
    setmobi_id1(word);
  };

  const handleDragOver = (e) => {
    e.preventDefault();
  };

  const handleOnnext = () => {
    if (tablecount >= jsondata.length) {
      console.error("No more data available. Cannot go to the next.");
      return;
    }
    setTablecount((prev) => prev + 1);
    setScore((prev) => prev + 1);
    setPara([]);
    setBlankspaces([]);
    setBsword([]);
    setCorrectcount(0);
    setFlag(true);
    ReactGA.event({
      action:
        "English Data interpretation | CDAC-OlabsNxtG-En-28 | Clicked on 'Next button",
      category: "English CDAC-OlabsNxtG-En-28 | Pie chart page 'Next' button clicked",
      label:
        "English CDAC-OlabsNxtG-En-28 | Pie chart page 'Next' button clicked to perform another piechart example.",
    });
    SendLogData(
      sendJsonMessage,
      pageName,
      'Pie chart page "Next" button.',
      "Clicked",
      'Pie chart page "Next" button clicked perform next pie chart data interpretation.'
    );
  };

  const handleskipbtn = () => {
    if (tablecount >= jsondata.length) {
      console.error("No more data available. Cannot go to the next.");
      return;
    }
    setTablecount((prev) => prev + 1);
    setPara([]);
    setBlankspaces([]);
    setBsword([]);
    setCorrectcount(0);
    setFlag(true);
  }

  const handleWrongClick = (e) => {
    const bsoriginalword = e.target.id;
    blankspaces.map((ele) => {
      if (bsoriginalword == ele.word) {
        const feedback = ele.feedback;
        Swal.fire({
          title: "Incorrect Word!",
          text: `${feedback}`,
          icon: "error",
          confirmButtonText: "Ok",
        });
      }
    });
  };

  const restartbtn = () => {
    ReactGA.event({
      action:
        'English Data interpretation| CDAC-OlabsNxtG-En-28 | Clicked on "Restart" button',
      category: 'English CDAC-OlabsNxtG-En-28 | "Restart" button clicked',
      label:
        'English CDAC-OlabsNxtG-En-28 | "Restart" button clicked and Pie chart data interpretation restarted',
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      '"Restart" button',
      "Clicked",
      '"Restart" button clicked and pie chart data interpretation restart.'
    );

    setTablecount(0);
    setPara([]);
    setBlankspaces([]);
    setBsword([]);
    setCorrectcount(0);
    setFlag1(false);
  };

  const handlemainmenubtn = () => {
    ReactGA.event({
      action:
        'English Data interpretation| CDAC-OlabsNxtG-En-28 | Clicked on "Main menu" button',
      category: 'English CDAC-OlabsNxtG-En-28 | "Main menu" button clicked',
      label:
        'English CDAC-OlabsNxtG-En-28 | "Main menu" button clicked and main menu displayed.',
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      '"Main menu" button',
      "Clicked",
      '"Main menu" button clicked and main menu displayed.'
    );
    navigate("/launchpage/englishactivity");
  };

  const handleClose1 = () => {
    setOpen1(false);
  };

  const handleHelp = () => {
    setOpen1(true);
    setHeplok(true);
    ReactGA.event({
      action:
        'English Data interpretation| CDAC-OlabsNxtG-En-28 | Clicked on "Help" button',
      category: 'English CDAC-OlabsNxtG-En-28 | "Help" button clicked',
      label:
        'English CDAC-OlabsNxtG-En-28 | "Help" button clicked for Pie chart data interpretation for instructions.',
    });
    SendLogData(
      sendJsonMessage,
      pageName,
      '"Help" button',
      "Clicked",
      '"Help" button clicked for pie chart data interpretation instructions.'
    );
  };

  const menuslelect = () => {
    navigate("/launchpage/englishactivity")
  }

  return (
    <div
      className="row"
      style={{
        width: "100vw",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <Pie_Instructions
        handleClose1={handleClose1}
        open1={open1}
        setOpen1={setOpen1}
        heplok={heplok}
      />
      {flag1 == true ? (
        <div className="col-sm-12 align-items-center justify-content-center">
          <div
            className="d-flex justify-content-end  text-center"
            variant="contained"
            onClick={menuslelect}
          >
            <img src={menu} title={t("select_graph")} style={{borderRadius: "14px", marginRight:"5px", marginTop:"2px"}}></img>
          </div>
          <div
            className="d-flex align-items-center justify-content-center"
            style={{
              display: "inline-block",
              position: "absolute",
              top: "50%",
              left: "50%",
              transform: "translate(-50%, -50%)",
            }}
          >

            <div
              className="text-center"
              style={{
                boxShadow: "rgba(0, 0, 0, 0.24) 0px 3px 8px",
                padding: "7vh 4vh 7vh 4vh",
                background: "#EDF6FA",
              }}
            >
              <p style={{ fontWeight: "bolder", fontSize: "calc(.6rem + .4vw)" }}>
                You have completed {score} of {Object.keys(jsondata).length} pie chart data interpretation. <br></br>Click on the "RESTART" button to practice pie chart data interpretation again.
              </p>
              <div>
                <Button variant="contained" onClick={restartbtn} style={{fontSize: "calc(.6rem + .4vw)", backgroundColor: "#0F477E"}}>
                  {t("restart")}
                </Button>
              </div>
              <p style={{ fontWeight: "bolder", fontSize: "calc(.6rem + .4vw)", marginTop: "1vh" }}>To start with other types of data interpretation, click on the "MAIN MENU" button.</p>
              <div>
                <Button variant="contained" onClick={handlemainmenubtn} style={{fontSize: "calc(.6rem + .4vw)", backgroundColor: "#0F477E"}}>
                  {t("mainmenu")}
                </Button>
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="">
          <div className="d-flex justify-content-end mb-2">
            <div className="col text-center" style={{ fontSize: "calc(1rem + .4vw)" }} >
              <b>Pie chart</b>
            </div>
            <div
              className=" text-center "
              variant="contained"
              onClick={menuslelect}
            >
              <img src={menu} title={t("select_graph")}></img>
            </div>
            <div className=" text-center" onClick={handleHelp} style={{ marginRight: "5px" }}>
              <img
                src={help}
                alt="Help"
                title={t("help")}
                style={{ cursor: "pointer" }}
              />
            </div>
          </div>

          {/* Chart + Paragraph Area */}
          <div className="row" style={{}}>
            <div className="col-12 col-md-6 mb-3 d-flex" style={{ height: "42.5vh" }}>
              <div
                className="w-100"
                style={{
                  background: "#EDF6FA",
                  boxShadow: "0px 4px 7px #00000029",
                  borderRadius: "10px",
                  padding: "1vh",
                  flexGrow: 1,
                  position: "relative", // Make the outer container relative
                }}
              >
                {/* Wrapper for canvas and caption */}
                <div style={{ position: "relative", width: "100%", height: "100%", paddingBottom: "25px" }}>
                  <canvas id="myChart" style={{ width: "100%", height: "100%" }}></canvas>
                  <p
                    className="text-center"
                    style={{
                      position: "absolute",
                      left: "50%",
                      transform: "translateX(-50%)",
                      margin: 0,
                      fontSize: "calc(.6rem + .4vw)"
                    }}
                  >
                    Fig: {chartcaption}
                  </p>
                </div>
              </div>
            </div>
            {/* Paragraph/Drop Area Section */}
            <div className="col-12 col-md-6 mb-3 d-flex" style={{ height: "42.5vh" }}>

              <div
                className="w-100"
                style={{
                  background: "#EDF6FA",
                  boxShadow: "0px 4px 7px #00000029",
                  borderRadius: "10px",
                  padding: "2vh",
                  overflowY: "auto",
                  flexGrow: 1,
                }}
              >
                <div className="text-center" style={{ fontSize: "calc(.6rem + .4vw)" }} dangerouslySetInnerHTML={{ __html: previnfo }}></div>
                <br></br>
                <br></br>
                {Array.isArray(para) && para.length > 0
                  ? (() => {
                    const processedWords = new Set();
                    return para.map((paraword, index) => {
                      const endsWithPeriod = paraword.endsWith(".");
                      const wordWithoutPeriod = paraword.replace(/[.,]$/, "");
                      const blankspace = blankspaces.find(
                        (bspace) =>
                          bspace.word === wordWithoutPeriod &&
                          !processedWords.has(bspace.word)
                      );
                      const isBlankspace = !!blankspace;

                      if (isBlankspace) {
                        processedWords.add(blankspace.word);
                        return (
                          <span
                            key={index}
                            id={blankspace.word}
                            style={{ color: "black", marginRight: "4px", padding: '5px', fontSize: "calc(.6rem + .4vw)" }}
                            onDrop={handleOndrop1}
                            onTouchEnd={handleOntouchend}
                            onDragOver={handleDragOver}
                            onClick={handleWrongClick}
                          >
                            __________
                            {endsWithPeriod && <span>.</span>}{" "}
                          </span>
                        );
                      }

                      return (
                        <span key={index} style={{ color: "black", marginRight: "4px", fontSize: "calc(.6rem + .4vw)" }}>
                          {paraword}{" "}
                        </span>
                      );
                    });
                  })()
                  : ""}
              </div>
            </div>
          </div>

          {/* Draggable Words Area */}
          <div
            className="d-flex justify-content-around flex-wrap mt-4"
            style={{
              background: "#EDF6FA",
              borderRadius: "10px",
              boxShadow: "0px 4px 7px #00000029",
              padding: "2%",
              fontWeight: "bolder",
              margin: "10px",
            }}
          >
            {bsword.map((word, idx) => (
              <div
                key={idx}
                style={{
                  borderRadius: "5px",
                  padding: "0.5vh 1vh",
                  background: "#F5B946",
                  cursor: "grabbing",
                  margin: "5px",
                  fontSize: "calc(.6rem + .4vw)"
                }}
                id={word}
                draggable="true"
                onDragStart={handledragstart}
                onTouchStart={handletouchstart}
              >
                {word}
              </div>
            ))}
          </div>

          {/* Next Button */}
          <div className="d-flex justify-content-around mt-2">
            <Button
              variant="contained"
              onClick={handleskipbtn}
              sx={{ backgroundColor: "#0F477E" }}
            >
              {t("skip")}
            </Button>
            <Button
              variant="contained"
              onClick={handleOnnext}
              disabled={flag}
              sx={{ backgroundColor: "#0F477E" }}
            >
              {t("next")}
            </Button>
          </div>
        </div>


      )}
    </div>
  );
}

export default PieChild;
