import { useEffect, useState } from "react";
import jsondata from "../json/linerechart.json";
import arrayShuffle from "array-shuffle";
import help from "../Images/help.png";
import { Button, Checkbox, FormControlLabel, FormGroup, Tooltip } from "@mui/material";
import { Carousel } from "react-bootstrap";
import {
  LineChart,
  ResponsiveContainer,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
} from "recharts";
import Swal from "sweetalert2";
import Line_Instructions from "./Line_instructions";
import { useTranslation } from "react-i18next";
import ReactGA from "react-ga4";
import useWebSocket from "react-use-websocket";
import logconfig from "../config/dbconfig.js";
import { SendLogData } from "../config/wslog.js";
import { useNavigate } from "react-router-dom";
import menu from "../Images/select_graph.png";

function LineRechart() {
  const [mainarr, setMainarr] = useState(Object.values(jsondata));
  var [tablecount, setTablecount] = useState(0);
  const [shuffled, setShuffled] = useState([]);
  const [open1, setOpen1] = useState(false);
  const [heplok, setHeplok] = useState(false);
  const [flag1, setFlag1] = useState(false);
  const [pointsarr, setPointsarr] = useState([]);
  const [questionsarr, setQuestionsarr] = useState([]);
  var [para, setPara] = useState();
  var [xaxisvals, setXaxisvals] = useState([]);
  var [yaxisvals, setYaxisvals] = useState([]);
  var [xkey, setXkey] = useState();
  var [ykey, setYkey] = useState();
  var [arr, setArr] = useState([]);
  const [activeIndex, setActiveIndex] = useState(0);
  const [selectedPoints, setSelectedPoints] = useState([]);
  const [selectedId, setSelectedId] = useState([]);
  var updatedId = [];
  const [lastCheckedIndex, setLastCheckedIndex] = useState(-1);
  var [flag, setFlag] = useState(false);
  const [aspect, setAspect] = useState(2); // Default aspect ratio
  const [isComplete, setIsComplete] = useState(false);
  const navigate = useNavigate();
  var keys;
  const { t, i18n } = useTranslation();
  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const [pageName, setPageName] = useState("Line chart page");
  let [score, setScore] = useState(0);
  var [chartcaption, setChartcaption] = useState("");
  let [previnfo, setPrevinfo] = useState();

  useEffect(() => {
    const updateAspect = () => {
      const width = window.innerWidth;
      if (width >= 1200) {
        setAspect(3); // Large devices
      } else if (width >= 768) {
        setAspect(2); // Medium devices
      } else {
        setAspect(1); // Small devices
      }
    };
    // Set initial aspect ratio
    updateAspect();
    // Add event listener to update on window resize
    window.addEventListener("resize", updateAspect);
    // Cleanup the event listener
    return () => window.removeEventListener("resize", updateAspect);
  }, []);

  useEffect(() => {
    if (tablecount >= mainarr.length) {
      setFlag1(true);
    } else {
      setShuffled(arrayShuffle(mainarr));
      setPointsarr(mainarr[tablecount].data.points_set);
      setQuestionsarr(mainarr[tablecount].data.question_set);
      para = mainarr[tablecount].data.paragraph;
      setPara(para);
      setArr(mainarr[tablecount].linechart);
      setChartcaption(mainarr[tablecount].data.caption)
      setPrevinfo(mainarr[tablecount].data.prev_details)
      mainarr[tablecount].linechart.map((point) => {
        keys = Object.keys(point);
        setXaxisvals((xaxisvals) => [...xaxisvals, point.xaxis]);
        setYaxisvals((yaxisvals) => [...yaxisvals, point.y_axis]);
      });
      if (keys.length >= 2) {
        setXkey(keys[0]); // Assume first key for X-axis
        setYkey(keys[1]); // Assume second key for Y-axis
      }
    }
  }, [mainarr, tablecount]);

  const handleClose1 = () => {
    setOpen1(false);
  };

  const handleHelp = () => {
    setOpen1(true);
    setHeplok(true);
    ReactGA.event({
      action:
        'English Data interpretation| CDAC-OlabsNxtG-En-28 | Clicked on "Help" button',
      category: 'English CDAC-OlabsNxtG-En-28 | "Help" button clicked',
      label:
        'English CDAC-OlabsNxtG-En-28 | "Help" button clicked for Line chart data interpretation instructions.',
    });
    SendLogData(
      sendJsonMessage,
      pageName,
      '"Help" button',
      "Clicked",
      '"Help" button clicked for Line chart data interpretation instructions.'
    );
  };

  const restartbtn = () => {
    ReactGA.event({
      action:
        'English Data interpretation| CDAC-OlabsNxtG-En-28 | Clicked on "Restart" button',
      category: 'English CDAC-OlabsNxtG-En-28 | "Restart" button clicked',
      label:
        'English CDAC-OlabsNxtG-En-28 | "Restart" button clicked and Line chart data interpretation restarted',
    });
    SendLogData(
      sendJsonMessage,
      pageName,
      '"Restart" button',
      "Clicked",
      '"Restart" button clicked and Line chart data interpretation restart.'
    );
    window.location.reload();
  };

  const handlemainmenubtn = () => {
    ReactGA.event({
      action:
        'English Data interpretation| CDAC-OlabsNxtG-En-28 | Clicked on "Main menu" button',
      category: 'English CDAC-OlabsNxtG-En-28 | "Main menu" button clicked',
      label:
        'English CDAC-OlabsNxtG-En-28 | "Main menu" button clicked and main menu displayed.',
    });
    SendLogData(
      sendJsonMessage,
      pageName,
      '"Main menu" button',
      "Clicked",
      '"Main menu" button clicked and main menu displayed.'
    );
    navigate("/launchpage/englishactivity");
  };

  const handleChange = (event) => {
    const val = parseInt(event.target.value);
    const id = parseInt(event.target.id);
    var feedback = "";
    pointsarr.map((ele) => {
      if (ele.key == lastCheckedIndex + 1) {
        feedback = ele.feedback;
      }
    });
    // Ensure checkboxes are checked in sequence
    if (id !== lastCheckedIndex + 1) {
      Swal.fire({
        text: `${feedback}`,
        icon: "error",
      });
      event.preventDefault(); // Prevent the checkbox from being checked
      return;
    }
    // setChecked(event.target.checked);
    setSelectedPoints((selectedPoints) => [...selectedPoints, val]);
    if (updatedId.includes(id)) {
      alert("already there");
    } else {
      updatedId = [...selectedId, id];
      setSelectedId(updatedId);
      Swal.fire({
        html: "Point plotted successfully <br></br> Click on next button.",
        icon: "success",
      });
      setFlag(true);
    }
    // Update the last checked index
    setLastCheckedIndex(id);
  };
  const filteredData = arr.filter((d) => selectedPoints.includes(d.y_axis));
  const CustomizedLabel = (props) => {
    const { x, y, stroke, value, cf } = props;
    return (
      <>
        {arr[0] && value === arr[0].y_axis && (
          <text
            x={x}
            y={y}
            dy={-6}
            fill={stroke}
            fontSize={15}
            textAnchor="middle"
          >
            A ({arr[0].xaxis}, {value})
          </text>
        )}
        {value === arr[1].y_axis && (
          <text
            x={x}
            y={y}
            dy={-6}
            fill={stroke}
            fontSize={15}
            textAnchor="middle"
          >
            B ( {arr[1].xaxis}, {value})
          </text>
        )}
        {value === arr[2].y_axis && (
          <text
            x={x}
            y={y}
            dy={-6}
            fill={stroke}
            fontSize={15}
            textAnchor="middle"
          >
            C ( {arr[2].xaxis}, {value})
          </text>
        )}
        {value === arr[3].y_axis && (
          <text
            x={x}
            y={y}
            dy={-6}
            fill={stroke}
            fontSize={15}
            textAnchor="middle"
          >
            D ( {arr[3].xaxis}, {value})
          </text>
        )}
        {value === arr[4].y_axis && (
          <text
            x={x}
            y={y}
            dy={-6}
            fill={stroke}
            fontSize={15}
            textAnchor="middle"
          >
            E ( {arr[4].xaxis}, {value})
          </text>
        )}
      </>
    );
  };

  const handlePrev = () => {
    if (activeIndex > 0) {
      // Decrement the active index
      setActiveIndex((prevIndex) => prevIndex - 1);
      // Remove the last selected point
      if (selectedPoints.length > 0 && selectedId.length > 0) {
        const updatedPoints = [...selectedPoints];
        const updatedIds = [...selectedId];
        updatedPoints.pop(); // Remove the last selected point
        updatedIds.pop(); // Remove the last selected checkbox ID
        // Update the state
        setSelectedPoints(updatedPoints);
        setSelectedId(updatedIds);
        // Update lastCheckedIndex to the new last element in updatedIds, or -1 if empty
        setLastCheckedIndex(
          updatedIds.length > 0 ? updatedIds[updatedIds.length - 1] : -1
        );
      }
    }
  };

  const handleNext = () => {
    if (activeIndex < questionsarr.length - 1) {
      setActiveIndex((prevIndex) => prevIndex + 1);
      setFlag(false);
    } else {
      setIsComplete(true);
    }
  };

  const handlenextgraph = () => {
    tablecount = tablecount + 1;
    setTablecount(tablecount);
    setScore((prev) => prev + 1);
    setFlag1(false);
    setIsComplete(false);
    setLastCheckedIndex(-1);
    setActiveIndex(0);
    setArr([]);
    setXaxisvals([]);
    setYaxisvals([]);
    setFlag(false);
    ReactGA.event({
      action:
        "English Data interpretation | CDAC-OlabsNxtG-En-28 | Clicked on 'Next button",
      category: "English CDAC-OlabsNxtG-En-28 | Line chart page 'Next' button clicked",
      label:
        "English CDAC-OlabsNxtG-En-28 | Line chart page 'Next' button clicked to perform another Line chart example.",
    });
    SendLogData(
      sendJsonMessage,
      pageName,
      'Line chart page "Next" button.',
      "Clicked",
      'Line chart page "Next" button clicked perform next Line chart data interpretation.'
    );
  };

  const menuslelect = () => {
    navigate("/launchpage/englishactivity")
  }

  return (
    <div
      className="row bg-white"
      style={{
        width: "100vw",
        height: "100%",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <Line_Instructions
        handleClose1={handleClose1}
        open1={open1}
        setOpen1={setOpen1}
        heplok={heplok}
      />
      {flag1 ? (
        <div className="col-sm-12 align-items-center justify-content-center">
          <div
              className="d-flex justify-content-end text-center "
              variant="contained"
              onClick={menuslelect}
            >
              <img src={menu} title={t("select_graph")}></img>
            </div>
          <div
            className="d-flex align-items-center justify-content-center"
            style={{
              display: "inline-block",
              position: "absolute",
              top: "50%",
              left: "50%",
              transform: "translate(-50%, -50%)",
            }}
          >

            <div
              className="text-center"
              style={{
                boxShadow: "rgba(0, 0, 0, 0.24) 0px 3px 8px",
                padding: "7vh 4vh 7vh 4vh",
                background: "#EDF6FA",
              }}
            >
              <p style={{ fontWeight: "bolder", fontSize: "calc(.6rem + .4vw)" }}>
                You have completed {score} of {Object.keys(jsondata).length} line graph data interpretation.<br></br>Click on the "RESTART" button to practice line graph data interpretation again.
              </p>
              <div>
                <Button variant="contained" onClick={restartbtn} style={{fontSize: "calc(.6rem + .4vw)", backgroundColor: "#0F477E"}}>
                  {t("restart")}
                </Button>
              </div>
              <p style={{ fontWeight: "bolder", fontSize: "calc(.6rem + .4vw)", marginTop: "1vh" }}>To start with other types of data interpretation, click on the "MAIN MENU" button.</p>
              <div>
                <Button variant="contained" onClick={handlemainmenubtn} style={{fontSize: "calc(.6rem + .4vw)", backgroundColor: "#0F477E"}}>
                  {t("mainmenu")}
                </Button>
              </div>
            </div>
          </div>
        </div>
      ) : isComplete ? (
        <div className="row d-flex justify-content-center align-items-center bg-white">
          <div className="d-flex justify-content-end">
           <div
              className="text-center "
              variant="contained"
              onClick={menuslelect}
            >
              <img src={menu} title={t("select_graph")}></img>
            </div>
            <div
              className="text-center"
              variant="contained"
              onClick={handleHelp}
            >
              <img src={help} title={t("help")} alt="Help" />
            </div>
          </div>
          <div
            className="row d-flex justify-content-center align-items-center"
            style={{}}
          >
            <div className="col-lg-9 col-md-9 col-sm-12">
              <ResponsiveContainer aspect={aspect}>
                <LineChart data={filteredData} margin={{ top: 20, right: 30, left: 20, bottom: 20 }}>
                  <CartesianGrid />
                  <XAxis
                    dataKey={xkey}
                    interval={"preserveStartEnd"}
                    domain={xaxisvals}
                    label={{ value: 'X-Axis ', position: 'bottom', offset: 0 }}
                  />

                  {/* Y-Axis with label */}
                  <YAxis
                    dataKey={ykey}
                    domain={yaxisvals}
                    label={{ value: 'Y-Axis ', angle: -90, position: 'insideLeft', offset: 0 }}
                  />
                  <Tooltip />

                  <Line
                    type="linear"
                    dataKey={ykey}
                    stroke="#8884d8"
                    label={<CustomizedLabel />}
                    // activeDot={{ r: 2 }}
                    dot={{
                      stroke: "#8884d8",
                      strokeWidth: 2,
                      r: 5,
                      fill: "#fff",
                    }}
                  />
                </LineChart>
              </ResponsiveContainer>
            </div>
            <div
              className="col-lg-9 col-md-9 col-sm-12 mt-5"
              style={{
                background: "#EDF6FA",
                borderRadius: "10px",
                boxShadow: "0px 3px 6px #00000029",
                color: "#000000",
                opacity: "1",
                padding: "2%",
                fontWeight: "bolder",
                fontSize: "calc(.6rem + .4vw)"
              }}
            >
              {para}
            </div>
            <div className="d-flex justify-content-around mt-2">
              <Button variant="contained" onClick={handlenextgraph} sx={{ backgroundColor: "#0F477E",fontSize: "calc(.6rem + .4vw)" }}>
                {t("nextgraph")}
              </Button>
            </div>
          </div>
        </div>
      ) : (
        <div
          className="row d-flex justify-content-center align-items-center"
          style={{ height: "99%" }}
        >
          <div className="d-flex justify-content-end">
            <div className="col text-center" style={{ fontSize: "calc(1rem + .4vw)" }} >
              <b>Line graph</b>
            </div>
            <div
              className="text-center "
              variant="contained"
              onClick={menuslelect}
            >
              <img src={menu} title={t("select_graph")}></img>
            </div>
            <div
              className="text-center"
              variant="contained"
              onClick={handleHelp}
            >
              <img src={help} title={t("help")} alt="Help" />
            </div>
          </div>

          <div className="row d-flex align-items-center">
            <div className="col-lg-9 col-md-9 col-sm-12">
              <ResponsiveContainer aspect={aspect}>
                <LineChart data={filteredData} margin={{ top: 20, right: 30, left: 20, bottom: 20 }}>
                  <CartesianGrid />

                  {/* X-Axis with label */}
                  <XAxis
                    dataKey={xkey}
                    interval={"preserveStartEnd"}
                    domain={xaxisvals}
                    label={{ value: 'X-Axis ', position: 'bottom', offset: 0 }}
                  />

                  {/* Y-Axis with label */}
                  <YAxis
                    dataKey={ykey}
                    domain={yaxisvals}
                    label={{ value: 'Y-Axis ', angle: -90, position: 'insideLeft', offset: 0 }}
                  />

                  {/* <Legend /> */}
                  <Tooltip />

                  <Line
                    type="linear"
                    dataKey={ykey}
                    stroke="#8884d8"
                    label={<CustomizedLabel />}
                    dot={{
                      stroke: "#8884d8",
                      strokeWidth: 2,
                      r: 5,
                      fill: "#fff",
                    }}
                  />
                </LineChart>
              </ResponsiveContainer>

              <div className="">
                <p
                  className="text-center"
                  style={{
                    margin: 0,
                    fontSize: "calc(.6rem + .4vw)"
                  }}
                >
                  Fig: {chartcaption}
                </p>
              </div>


            </div>
            <div className="col-lg-3 col-md-3 col-sm-12 text-center" style={{ fontSize: "calc(.6rem + .4vw)" }}>
              <span>Check the following checkboxes to mark the points.</span>
              {pointsarr.length !== 0
                ? pointsarr.map((point, index) => (
                  <FormGroup
                    key={index}
                    style={{ justifyContent: "center", alignItems: "center" }}
                  >
                    <FormControlLabel
                      control={
                        <Checkbox
                          id={index}
                          checked={index <= lastCheckedIndex} // Allow only in-sequence checkboxes to be checked
                          onChange={flag ? () => { } : handleChange}
                        />
                      }
                      label={point.point}
                      value={point.value}
                      sx={{
                        '& .MuiFormControlLabel-label': {
                          fontSize: "calc(.6rem + .4vw)",
                        }
                      }}
                    />
                  </FormGroup>
                ))
                : "No data available"}
            </div>
          </div>
          <div
            className=" justify-content-center align-items-center"
            style={{ height: "42.5vh", marginTop: "1vh" }}
          >
            <div className="text-center" style={{ fontSize: "calc(.6rem + .4vw)" }} dangerouslySetInnerHTML={{ __html: previnfo }}></div>
            <div className="d-flex justify-content-center align-items-center mt-1">
              <Carousel
                activeIndex={activeIndex}
                interval={null}
                prevLabel={null}
                nextLabel={null}
                style={{
                  backgroundColor: "#EDF6FA", // Carousel background color
                  borderRadius: "10px",       // Optional: rounded corners
                  width: "90%",               // Optional: control overall width
                }}
                prevIcon={
                  <span
                    aria-hidden="true"
                    className="carousel-control-prev-icon"
                    onClick={handlePrev}
                    style={{
                      cursor: activeIndex > 0 ? "pointer" : "not-allowed",
                      backgroundColor: "black",
                    }}
                  />
                }
                nextIcon={
                  <span
                    aria-hidden="true"
                    className="carousel-control-next-icon"
                    onClick={flag ? handleNext : null}
                    style={{
                      cursor:
                        activeIndex < questionsarr.length - 1
                          ? "pointer"
                          : "not-allowed",
                      backgroundColor: "black",
                    }}
                  />
                }
              >
                {questionsarr.map((question, index) => (
                  <Carousel.Item
                    key={index}
                    style={{
                      backgroundColor: "#EDF6FA",
                      height: "200px", // Set fixed height or use '100%' if parent is fixed
                      width: "100%",
                    }}
                  >
                    <div
                      className="d-flex justify-content-center align-items-center "
                      style={{
                        height: "100%",
                        width: "100%",
                        flexDirection: "column", //  Stack text vertically
                        textAlign: "center",     //  Center-align the text content
                        fontSize: "calc(.6rem + .4vw)"
                      }}
                    >
                      <p className="mb-2" style={{ fontWeight: "bold" }}>
                        {question.sentence}
                      </p>
                      <span className="mb-0" style={{ fontSize: "calc(.6rem + .4vw)" }}>{`Q${index + 1}: ${question.question}`}</span>
                    </div>
                  </Carousel.Item>

                ))}
              </Carousel>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default LineRechart;
